function evidence = f90_xmed09_extract_candidate_evidence(modelPath, outputDir)
%f90_xmed09_extract_candidate_evidence Dimension-aware official replay.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot, publicOutputRoot] = localRoots("F90-XMED-09");
addpath(sharedRoot, "-begin"); addpath(publicOutputRoot, "-begin");
cleanup = onCleanup(@() localRemovePaths(sharedRoot, publicOutputRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct("schema", "simuverity.formal90-fixed-evidence.v1", ...
    "task_id", "F90-XMED-09", "scenarios", official.scenarios, ...
    "output_contract", localOutputs, "input_builder", @localInputs, ...
    "requested_input_builder", @localInputs, ...
    "stop_time", @(~,~) double(official.simulation.stop_time_s), ...
    "postprocess", @localPostprocess, "static_audit", @localAudit, ...
    "evidence_sample_s", double(official.simulation.stop_time_s) / ...
        (double(official.simulation.evidence_points) - 1));
evidence = simuverity_run_candidate_evidence(modelPath, outputDir, spec);
evidence = localFinalize(evidence, outputDir);
end

function rows = localOutputs
rows = localRows(["HemodynamicState","AssistControlState","ChamberState"], ...
    [4 4 4]);
end

function inputs = localInputs(scenario, ~)
names = ["CardiacConditionMode","LVADConnected","AssistControllerMode", ...
    "BaroreflexEnabled","ResistanceVariationEnabled", ...
    "ElastanceVariationEnabled"];
inputs = struct;
for name = names
    inputs.(name) = double(scenario.(name));
end
end

function row = localPostprocess(row, outputs, ~, ~)
t = double(outputs.time_s(:));
h = double(outputs.HemodynamicState);
a = double(outputs.AssistControlState);
c = double(outputs.ChamberState);
tail = t >= max(t(1), t(end) - 20);
psai=h(:,1); pao=h(:,2); plv=h(:,3); vlv=h(:,4);
row.metrics = struct( ...
    "systemic_pressure_tail_mean_mmHg",mean(psai(tail)), ...
    "systemic_pressure_tail_min_mmHg",min(psai(tail)), ...
    "systemic_pressure_tail_max_mmHg",max(psai(tail)), ...
    "systemic_pressure_tail_pulsatility_mmHg",max(psai(tail))-min(psai(tail)), ...
    "systemic_target_tail_mae_mmHg",mean(abs(psai(tail)-75.0)), ...
    "aortic_pressure_tail_mean_mmHg",mean(pao(tail)), ...
    "left_ventricular_pressure_min_mmHg",min(plv), ...
    "left_ventricular_pressure_max_mmHg",max(plv), ...
    "left_ventricular_volume_min_mL",min(vlv), ...
    "left_ventricular_volume_max_mL",max(vlv), ...
    "left_ventricular_volume_excursion_mL",max(vlv(tail))-min(vlv(tail)), ...
    "assist_pressure_tail_mean_mmHg",mean(a(tail,1)), ...
    "assist_pressure_tail_span_mmHg",max(a(tail,1))-min(a(tail,1)), ...
    "controller_effort_tail_rms",sqrt(mean(a(tail,2).^2)), ...
    "controller_effort_tail_span",max(a(tail,2))-min(a(tail,2)), ...
    "iae_final",a(end,3),"itae_final",a(end,4), ...
    "right_atrial_pressure_min_mmHg",min(c(:,1)), ...
    "right_atrial_pressure_max_mmHg",max(c(:,1)), ...
    "right_ventricular_pressure_min_mmHg",min(c(:,2)), ...
    "right_ventricular_pressure_max_mmHg",max(c(:,2)), ...
    "left_atrial_pressure_min_mmHg",min(c(:,3)), ...
    "left_atrial_pressure_max_mmHg",max(c(:,3)), ...
    "right_ventricular_volume_min_mL",min(c(:,4)), ...
    "right_ventricular_volume_max_mL",max(c(:,4)), ...
    "hemodynamic_summary",sum(abs(diff(h(:,[1 3 4]),1,1)),"all"), ...
    "assist_summary",sum(abs(diff(a(:,1:2),1,1)),"all"), ...
    "all_finite",all(isfinite([h(:);a(:);c(:)])));
row.outputs = outputs;
row.offline_metrics = row.metrics;
row.valid = row.output_contract.all_required_pass && row.metrics.all_finite;
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
capacity = f90_xmed09_dynamic_capacity(model);
dynamicOrder = capacity.dynamic_capacity_units;
subsystems = nnz(string({structure.block_rows.block_type}) == "SubSystem");
outputsConnected = structure.connected_output_count == numel(spec.output_contract) && ...
    structure.nontrivial_output_source_count == numel(spec.output_contract);
coreDynamics = outputsConnected && dynamicOrder >= 20;
feedback = coreDynamics && (structure.signal_cycle_present || ...
    structure.physical_connection_block_count > 0 || structure.block_count >= 30);
audit = struct( ...
    "recursive_block_count",structure.block_count, ...
    "subsystem_count",subsystems, ...
    "dynamic_block_count",dynamicOrder, ...
    "dynamic_state_dimension",capacity.dynamic_state_dimension, ...
    "dynamic_kernel_output_port_count",capacity.dynamic_kernel_output_port_count, ...
    "dynamic_capacity_units",capacity.dynamic_capacity_units, ...
    "dynamic_state_block_count",capacity.dynamic_state_block_count, ...
    "dynamic_kernel_block_count",capacity.dynamic_kernel_block_count, ...
    "dynamic_capacity_policy",capacity.dynamic_capacity_policy, ...
    "heart_lvad_present",coreDynamics, ...
    "control_processing_present",feedback, ...
    "controller_present",feedback, ...
    "baroreflex_present",feedback, ...
    "measured_pressure_tag_present",outputsConnected, ...
    "assist_pressure_tag_present",outputsConnected, ...
    "control_effort_tag_present",outputsConnected, ...
    "initializer_present",true, ...
    "qualification_basis","candidate topology and published output bindings", ...
    "candidate_public_input_contract",true);
end

function evidence = localFinalize(evidence, outputDir)
rows = evidence.scenarios;
evidence.evaluation_subject = "candidate";
evidence.simulate_pass = ~isempty(rows) && all([rows.simulation_pass]);
evidence.all_official_evidence_valid = ~isempty(rows) && all([rows.valid]);
evidence.runtime_model_unchanged = evidence.binding_preserved;
evidence.EVIDENCE_COMPLETE = evidence.score_inputs_valid;
evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
localWriteJson(fullfile(outputDir,"evidence.json"),evidence);
end

function rows = localRows(names, widths)
rows = repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"),numel(names),1);
for index=1:numel(names)
    rows(index).name=names(index); rows(index).evidence_name=names(index);
    rows(index).width=widths(index);
end
end

function [taskRoot, sharedRoot, publicOutputRoot] = localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath")); tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared"); repoRoot=tasksRoot;
for index=1:3, repoRoot=fileparts(repoRoot); end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
publicOutputRoot=fullfile(repoRoot,"scripts","unified","public_output");
end

function localRemovePaths(sharedRoot, publicOutputRoot)
try, rmpath(sharedRoot); catch, end
try, rmpath(publicOutputRoot); catch, end
end

function localWriteJson(path, value)
temporary=string(path)+".staging-"+string(java.util.UUID.randomUUID);
fid=fopen(temporary,"w","n","UTF-8");
assert(fid>=0,"SimuVerity:F90:XMED09:Write","Cannot write candidate evidence.");
cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,jsonencode(value,PrettyPrint=true),"char"); clear cleanup
assert(movefile(temporary,path,"f"),"SimuVerity:F90:XMED09:Publish", ...
    "Cannot publish candidate evidence.");
end
